18K金手链，实付5440元
Available functions:
[
  {
    "name": "calculate_gift_contribution",
    "description": "Calculates an equal per-person contribution for a shared group cost from a total amount and the number of people splitting it. Use it when someone asks for each person's share of a group cost given as a total and a headcount. Do not use it for individual purchases or for price questions about a single item. It only divides the amount it is given and does not verify that total.",
    "input_schema": {
      "type": "object",
      "properties": {
        "headcount": {
          "type": "integer",
          "minimum": 2,
          "maximum": 30,
          "description": "Number of people sharing the cost, as a whole-number integer."
        },
        "total_amount": {
          "type": "integer",
          "minimum": 1,
          "maximum": 100000,
          "description": "Total cost in yuan as a whole-number integer."
        }
      },
      "required": [
        "headcount",
        "total_amount"
      ]
    }
  },
  {
    "name": "set_thermostat",
    "description": "Sets the room thermostat to a target temperature in degrees Celsius. Use it when someone asks to make the room warmer or cooler or names a room temperature. Do not use it for a car, an oven or a separate air conditioner. The target must be a whole number from 16 to 28.",
    "input_schema": {
      "type": "object",
      "properties": {
        "temperature": {
          "type": "integer",
          "minimum": 16,
          "maximum": 28,
          "description": "Target room temperature in whole degrees Celsius, from 16 to 28."
        }
      },
      "required": [
        "temperature"
      ]
    }
  },
  {
    "name": "operate_garage_door",
    "description": "Moves the garage door motor. Use it when someone asks to raise or lower the garage door, or to halt it while it moves. Do not use it for the front door lock or for the car itself. Make sure the doorway is clear before moving the door.",
    "input_schema": {
      "type": "object",
      "properties": {
        "action": {
          "type": "string",
          "enum": [
            "open",
            "close",
            "stop"
          ],
          "description": "What the garage door motor should do."
        }
      },
      "required": [
        "action"
      ]
    }
  },
  {
    "name": "start_robot_vacuum",
    "description": "Starts the robot vacuum cleaner in one room. Use it when someone asks to clean or vacuum the floor of a room. Do not use it for mopping, laundry or stopping a vacuum that is already running. It cleans only the chosen room.",
    "input_schema": {
      "type": "object",
      "properties": {
        "room": {
          "type": "string",
          "enum": [
            "living_room",
            "bedroom",
            "kitchen"
          ],
          "description": "Room the robot vacuum should clean."
        }
      },
      "required": [
        "room"
      ]
    }
  }
]
